/** Only touches a new synthetic note DB and media directory in a disposable CI emulator. Measures displayed Bitmap allocation, not process-wide peak RAM. */
final class NoteThumbnailChecks {
    private static final String PKG="com.supercubegame.pockettodo.v12.preview", REPEAT="thumb-repeat", MANY="thumb-many", BAD="thumb-invalid";
    private static final long ACT=8971;
    final Instrumentation ins; final Bundle args; final StringBuilder log; final Context c;
    final List<byte[]> bytes=new ArrayList<>(); final List<String> ids=new ArrayList<>(); final List<NoteDocument.Block> repeated=new ArrayList<>(),many=new ArrayList<>();
    MainActivity app;NoteEditorScreen editor;MediaRepository media;byte[] canonical; long deadline;String badKey;
    NoteThumbnailChecks(Instrumentation ins,Bundle args,StringBuilder log){this.ins=ins;this.args=args;this.log=log;c=ins.getTargetContext();}
    static void need(boolean ok,String why){if(!ok)throw new AssertionError("note-thumbnails: "+why);}
    private <T>T ui(Callable<T> job)throws Exception{FutureTask<T> task=new FutureTask<>(job);ins.runOnMainSync(task);return task.get();}
    private <T>T waitFor(String scope,Callable<T> job)throws Exception{long until=Math.min(deadline,SystemClock.uptimeMillis()+9000);do{T v=job.call();if(v!=null)return v;SystemClock.sleep(45);}while(SystemClock.uptimeMillis()<until);throw new AssertionError("note-thumbnails: not observed: "+scope);}
    static void collect(View v,String key,List<View> result){if(key.contentEquals(String.valueOf(v.getContentDescription())))result.add(v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)collect(g.getChildAt(i),key,result);}}
    View find(String key){List<View> all=new ArrayList<>();collect(app.getWindow().getDecorView(),key,all);need(all.size()<=1,"ambiguous synthetic widget");return all.isEmpty()?null:all.get(0);}
    private TextView ready(String id,TextView old,String info)throws Exception{return waitFor("loaded page",()->ui(()->{View v=find("note-selected-id");if(!(v instanceof TextView)||v==old||!v.isAttachedToWindow()||!v.hasWindowFocus()||!id.contentEquals(((TextView)v).getText()))return null;View pg=find("note-block-page-info");if(info==null?pg!=null:!(pg instanceof TextView)||!info.contentEquals(((TextView)pg).getText()))return null;return (TextView)v;}));}
    private TextView open(String n,String info)throws Exception{TextView old=ui(()->(TextView)find("note-selected-id"));ui(()->{editor.load(n);return true;});return ready(n,old,info);}
    private void step(String e){log.append("THUMB_NATIVE ").append(e).append(" PASS\n");}
    static int color(int k){return Color.rgb(29+15*k,72+8*k,121-4*k);}
    static byte[] png(int k)throws IOException{Bitmap b=Bitmap.createBitmap(512,384,Bitmap.Config.ARGB_8888);try{b.eraseColor(color(k));b.setPixel(1,1,Color.WHITE);ByteArrayOutputStream out=new ByteArrayOutputStream();need(b.compress(Bitmap.CompressFormat.PNG,100,out),"generate synthetic PNG");return out.toByteArray();}finally{b.recycle();}}
    private void seed()throws Exception{
        Path dir=c.getFilesDir().toPath().resolve(MainActivity.THUMB_MEDIA);Files.createDirectory(dir);media=new MediaRepository(dir,8L*1024*1024);
        Path file=c.getDatabasePath(MainActivity.THUMB_DB).toPath();Files.createDirectories(file.getParent());try(DirectoryStream<Path> side=Files.newDirectoryStream(file.getParent(),MainActivity.THUMB_DB+"-*")){need(!side.iterator().hasNext(),"existing fixture sidecar preserved");}Files.createFile(file);
        try(AppDatabase d=AppDatabase.openSchema4(c,MainActivity.THUMB_DB)){
            d.addCategory(1,"缩略图");d.addActivity(ACT,1,0,"合成图");for(int i=0;i<10;i++){byte[] r=png(i);String key=MediaRepository.digest(r);if(i!=9)need(key.equals(media.copy(new ByteArrayInputStream(r))),"stored byte identity");bytes.add(r);ids.add(key);d.registerMedia(key,"image/png",r.length);}
            byte[] bad={7,0,3,1,9};badKey=media.copy(new ByteArrayInputStream(bad));d.registerMedia(badKey,"image/png",bad.length);
            d.createNote(REPEAT,ACT,"同名笔记");repeated.add(NoteDocument.Block.text("rtext","文字未变",true));for(int i=0;i<24;i++)repeated.add(NoteDocument.Block.image("r"+i,ids.get(i%3),"固定说明",i%2==0));for(int i=0;i<2;i++)repeated.add(NoteDocument.Block.image("gone"+i,ids.get(9),"合成缺件",i==1));d.saveNote(REPEAT,repeated);
            d.createNote(MANY,ACT,"同名笔记");for(int i=0;i<9;i++){many.add(NoteDocument.Block.image("u"+i,ids.get(i),"初始说明",i%2==0));if(i==3||i==6)many.add(NoteDocument.Block.text("t"+i,"文字保留",true));}d.saveNote(MANY,many);
            d.createNote(BAD,ACT,"坏图");d.saveNote(BAD,Arrays.asList(NoteDocument.Block.image("bad",badKey,"合成坏图",true)));canonical=d.exportState();}
    }
    private byte[] state()throws Exception{try(AppDatabase d=AppDatabase.openSchema4(c,MainActivity.THUMB_DB)){return d.exportState();}}
    private void files(boolean repaired)throws Exception{for(int i=0;i<10;i++){if(i==9&&!repaired){need(!Files.exists(c.getFilesDir().toPath().resolve(MainActivity.THUMB_MEDIA).resolve(ids.get(i)),LinkOption.NOFOLLOW_LINKS),"missing fixture not created by display");continue;}need(Arrays.equals(bytes.get(i),Files.readAllBytes(media.path(ids.get(i)))),"source file changed");}need(Arrays.equals(new byte[]{7,0,3,1,9},Files.readAllBytes(media.path(badKey))),"invalid input rewritten");}
    static final class Counts{int refs;long summed,unique;Set<Bitmap> objects=Collections.newSetFromMap(new IdentityHashMap<Bitmap,Boolean>());Map<String,Bitmap> asset=new HashMap<>();}
    Counts inspect(List<NoteDocument.Block> all,int start,int end,boolean repaired)throws Exception{return ui(()->{Counts out=new Counts();ArrayList<View> ordered=new ArrayList<>();ViewGroup list=null;
        for(int i=0;i<all.size();i++){NoteDocument.Block b=all.get(i);String tag=b.kind==NoteDocument.Kind.TEXT?"note-text-":"note-image-";View v=find(tag+b.id);if(i<start||i>=end){need(v==null,"other page attached");continue;}need(v!=null&&v.isAttachedToWindow(),"current attached row");View row=v;
            if(b.kind==NoteDocument.Kind.TEXT){need(v instanceof TextView&&b.text.contentEquals(((TextView)v).getText()),"text block changed");}
            else{TextView pv=(TextView)find("note-image-privacy-"+b.id);need(pv!=null&&(b.privateContent?"私有图片":"非私有图片").contentEquals(pv.getText()),"private label changed");row=(View)v.getParent();int k=ids.indexOf(b.assetId);
                if(k<0||k==9&&!repaired){need(v instanceof TextView&&"图片副本不可用或方向无法确认".contentEquals(((TextView)v).getText()),"missing image disguised as bitmap");}
                else{need(v instanceof ImageView&&((ImageView)v).getDrawable() instanceof BitmapDrawable,"no bitmap drawable");Bitmap bit=((BitmapDrawable)((ImageView)v).getDrawable()).getBitmap();need(bit!=null&&!bit.isRecycled()&&!bit.isMutable()&&bit.getWidth()==512&&bit.getHeight()==384&&bit.getPixel(1,1)==Color.WHITE&&bit.getPixel(4,3)==color(k),"wrong or mutable displayed pixels");int alloc=bit.getAllocationByteCount();need(alloc>=512*384*4&&alloc<=4194304,"unexpected raster allocation");out.refs++;out.summed+=alloc;if(out.objects.add(bit))out.unique+=alloc;Bitmap previous=out.asset.put(b.assetId,bit);need(previous==null||previous==bit,"one asset decoded into distinct row buffers");}}
            if(list==null)list=(ViewGroup)row.getParent();need(row.getParent()==list,"wrong list");ordered.add(row);}
        need(out.objects.size()==out.asset.size()&&out.objects.size()<=4&&out.unique<=4L*4194304,"wrong retained distinct-asset budget");int last=-1;for(View v:ordered){int index=list.indexOfChild(v);need(index>last,"order changed");last=index;}return out;});}
    String page(int i){int[] a={1,6,11},b={5,10,11};return "第 "+(i+1)+" / 3 页，内容块 "+a[i]+" 至 "+b[i]+"（共 11）";}
    private TextView turn(TextView old,int target,boolean forward)throws Exception{ui(()->{View v=find(forward?"note-block-page-next":"note-block-page-prev");need(v instanceof Button&&v.isEnabled()&&v.isAttachedToWindow()&&v.performClick(),"native pager refused");return true;});return ready(MANY,old,page(target));}
    // An exact dialog, not a coordinate tap. Never send non-fixture text or interact with another package/window.
    private void node(String which,String label,boolean change)throws Exception{waitFor("owned caption dialog",()->{AccessibilityNodeInfo root=ins.getUiAutomation().getRootInActiveWindow();if(root==null)return null;try{if(!PKG.contentEquals(String.valueOf(root.getPackageName())))return null;List<AccessibilityNodeInfo> heads=root.findAccessibilityNodeInfosByText("图片说明与私有标记"),ns=change?root.findAccessibilityNodeInfosByText("image-caption"):root.findAccessibilityNodeInfosByViewId(which);try{int head=0;for(AccessibilityNodeInfo h:heads)if(h.isVisibleToUser()&&"图片说明与私有标记".contentEquals(String.valueOf(h.getText())))head++;if(head==0)return null;need(head==1,"ambiguous dialog");AccessibilityNodeInfo matched=null;for(AccessibilityNodeInfo n:ns)if(n.isEnabled()&&n.isVisibleToUser()&&PKG.contentEquals(String.valueOf(n.getPackageName()))&&(change?"image-caption".contentEquals(String.valueOf(n.getContentDescription()))&&"android.widget.EditText".contentEquals(String.valueOf(n.getClassName())):label.contentEquals(String.valueOf(n.getText())))){need(matched==null,"ambiguous action");matched=n;}if(matched==null)return null;Bundle b=new Bundle();if(change)b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,label);need(change?matched.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b):matched.performAction(AccessibilityNodeInfo.ACTION_CLICK),"owned caption action refused");return Boolean.TRUE;}finally{for(AccessibilityNodeInfo n:ns)n.recycle();for(AccessibilityNodeInfo n:heads)n.recycle();}}finally{root.recycle();}});}
    private void edit(boolean save)throws Exception{ui(()->{View v=find("note-image-edit-u4");need(v!=null&&v.isAttachedToWindow()&&v.isEnabled()&&v.performClick(),"edit owned metadata");return true;});node("","新合成说明",true);node(save?"android:id/button1":"android:id/button2",save?"保存":"取消",false);waitFor("original note window",()->ui(()->app.getWindow().getDecorView().hasWindowFocus()?Boolean.TRUE:null));}
    static void pageControls(){
        List<NoteDocument.Block> all=new ArrayList<>();need(NoteThumbnailLoad.page(all,0).count==1&&NoteThumbnailLoad.page(all,0).blocks.isEmpty(),"empty note");
        boolean refused=false;try{NoteThumbnailLoad.page(all,-1);}catch(IllegalArgumentException ok){refused=true;}need(refused,"invalid page");
        for(int i=0;i<41;i++)all.add(NoteDocument.Block.text("t"+i,"same",i%2==0));need(NoteThumbnailLoad.page(all,0).blocks.equals(all),"text only unchanged");
        all.clear();for(int i=0;i<33;i++)all.add(NoteDocument.Block.image("d"+i,"a","same",i%2==0));NoteThumbnailLoad.Page a=NoteThumbnailLoad.page(all,0),b=NoteThumbnailLoad.page(all,Integer.MAX_VALUE);need(a.count==2&&a.first==0&&a.end==32&&b.index==1&&b.first==32&&b.end==33,"32-row boundary and final page");
        boolean frozen=false;try{a.blocks.clear();}catch(UnsupportedOperationException ok){frozen=true;}need(frozen&&all.size()==33,"projection cannot mutate note");
        all.clear();for(int i=0;i<9;i++){all.add(NoteDocument.Block.image("p"+i,"a"+i,"same",i%2==0));if(i==3||i==6)all.add(NoteDocument.Block.text("tp"+i,"same",false));}List<NoteDocument.Block> flat=new ArrayList<>();int[] lo={0,5,10},hi={5,10,11};
        for(int i=0;i<3;i++){NoteThumbnailLoad.Page p=NoteThumbnailLoad.page(all,i);need(p.first==lo[i]&&p.end==hi[i]&&p.count==3&&p.index==i,"independent page bounds");flat.addAll(p.blocks);}need(all.equals(flat),"every stable block appears exactly once in order");
        all.clear();int[] keys={1,2,3,4,1,2,3,4,5};for(int i=0;i<keys.length;i++)all.add(NoteDocument.Block.image("mix"+i,"id"+keys[i],"same",i%2==1));need(NoteThumbnailLoad.page(all,0).end==8&&NoteThumbnailLoad.page(all,1).blocks.get(0).id.equals("mix8"),"repeat uses no new unique slot");
    }
    void run()throws Exception{
        pageControls();
        int api=Build.VERSION.SDK_INT;String nonce=args.getString("thumbNonce");need((api==26||api==34)&&Integer.toString(api).equals(args.getString("expectedApi"))&&PKG.equals(c.getPackageName())&&"ranchu".equals(Build.HARDWARE)&&nonce!=null&&nonce.matches("[0-9]+-[1-9][0-9]*-"+api),"only disposable emulator");log.append("THUMB_SCOPE api=").append(api).append(" nonce=").append(nonce).append(" package=").append(PKG).append(" hardware=ranchu synthetic=true\n");deadline=SystemClock.uptimeMillis()+85000;seed();
        Bitmap mutable=Bitmap.createBitmap(16,12,Bitmap.Config.ARGB_8888);mutable.eraseColor(Color.BLUE);Bitmap frozen=NoteEditorScreen.displayBitmap(mutable);need(frozen!=mutable&&!frozen.isMutable()&&mutable.isRecycled()&&frozen.getPixel(3,3)==Color.BLUE&&NoteEditorScreen.displayBitmap(frozen)==frozen&&!frozen.isRecycled(),"share-safe sample");frozen.recycle();step("immutable_display_buffer_and_owned_temporary");
        AccessibilityServiceInfo info=ins.getUiAutomation().getServiceInfo();int flags=info.flags;info.flags|=AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;ins.getUiAutomation().setServiceInfo(info);MainActivity.isolatedNoteThumbnailTest=true;
        try{app=(MainActivity)ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor("isolated workbench ready",()->ui(()->{View v=find("activity-"+ACT);return v!=null&&v.isEnabled()?Boolean.TRUE:null;}));editor=new NoteEditorScreen(app.shortcutTestScreen(),ACT,"合成图",()->{});open(REPEAT,null);Counts repeat=inspect(repeated,0,repeated.size(),false);need(repeat.refs==24&&repeat.objects.size()==3&&repeat.summed==8*repeat.unique,"same-reference fixture mismatch");log.append("THUMB_BYTES rows=24 unique=3 rowBytes=").append(repeat.summed).append(" uniqueBytes=").append(repeat.unique).append('\n');step("real_note_24_rows_three_bitmap_allocations");
            open(BAD,null);inspect(Collections.singletonList(NoteDocument.Block.image("bad",badKey,"合成坏图",true)),0,1,false);files(false);need(Arrays.equals(canonical,state()),"readonly fallback mutated state");step("missing_invalid_render_as_markers_no_source_write");
            TextView one=open(MANY,page(0));Counts left=inspect(many,0,5,false);Button detached=(Button)ui(()->find("note-block-page-next"));TextView two=turn(one,1,true);Counts middle=inspect(many,5,10,false);ui(()->{need(!detached.isAttachedToWindow(),"stale reference still attached");detached.performClick();return true;});TextView three=turn(two,2,true);Counts right=inspect(many,10,11,false);need(left.refs==4&&middle.refs==4&&right.refs==1&&ui(()->!find("note-block-page-next").isEnabled()),"all nine distinct assets/page endpoints");log.append("THUMB_PAGES unique=4,4,1 retained=").append(left.unique).append(',').append(middle.unique).append(',').append(right.unique).append('\n');two=turn(three,1,false);need(Arrays.equals(canonical,state()),"paging changed DB");files(false);step("nine_distinct_forward_back_no_drop_or_stale_page");
            edit(false);need(Arrays.equals(canonical,state()),"cancel changed state");edit(true);ready(MANY,two,page(1));try(AppDatabase d=AppDatabase.openSchema4(c,MainActivity.THUMB_DB)){List<NoteDocument.Block> after=d.noteBlocks(MANY);need(after.size()==many.size()&&d.noteBlocks(REPEAT).size()==repeated.size(),"edited page replaced whole note");for(int i=0;i<after.size();i++){NoteDocument.Block a=after.get(i),b=many.get(i);need(a.id.equals(b.id)&&a.kind==b.kind&&Objects.equals(a.assetId,b.assetId)&&Objects.equals(a.text,b.text)&&a.privateContent==b.privateContent&&a.caption.equals(b.id.equals("u4")?"新合成说明":b.caption),"unrelated block rewritten");}canonical=d.exportState();}step("middle_page_confirm_cancel_and_offpage_rows_preserved");
            need(ids.get(9).equals(media.copy(new ByteArrayInputStream(bytes.get(9)))),"supply exact previously missing fixture");open(REPEAT,null);Counts next=inspect(repeated,0,repeated.size(),true);need(next.refs==26&&next.objects.size()==4&&Collections.disjoint(repeat.objects,next.objects),"global cache or stale error survived reopen");files(true);need(Arrays.equals(canonical,state()),"reopening changed database");step("fresh_load_recovers_missing_no_global_cache_state_exact");
        }finally{try{if(app!=null){TodayScreen host=app.shortcutTestScreen();ins.runOnMainSync(app::finish);ins.waitForIdleSync();need(host==null||host.awaitShortcutClose(),"note worker did not close");}}finally{MainActivity.isolatedNoteThumbnailTest=false;info.flags=flags;ins.getUiAutomation().setServiceInfo(info);}}
    }
}
